css:
body {
	margin: 0;
	font-family: sans-serif;
}

.settings.mk-1pv9424 {
				padding: 24px;
				background: #fdfcf9;
			}
			.heading.mk-1pv9424 {
				font-size: 26px;
				font-weight: 700;
				color: #264653;
			}
			.toggle.mk-1pv9424 {
				display: block;
				width: 100%;
				margin-top: 16px;
				padding: 12px 16px;
				border: 2px solid #264653;
				border-radius: 10px;
				background: #ffffff;
				color: #264653;
				font-family: inherit;
				font-size: 18px;
				text-align: left;
			}
			.toggle.on.mk-1pv9424 {
				background: #264653;
				color: #ffffff;
			}
			.status.mk-1pv9424 {
				margin-top: 12px;
				padding: 10px 16px;
				background: #e9ecef;
				color: #495057;
				font-size: 16px;
			}
			.status[ui-active].mk-1pv9424 {
				background: #2a9d8f;
				color: #ffffff;
			}
			.next.mk-1pv9424 {
				display: block;
				margin-top: 16px;
				color: #264653;
				font-size: 17px;
				text-decoration: none;
			}
			@media (prefers-color-scheme: dark) {
				.settings.mk-1pv9424 {
					background: #1d1b16;
				}
				.heading.mk-1pv9424 {
					color: #f4f1ea;
				}
				.next.mk-1pv9424 {
					color: #e9c46a;
				}
			}
